<?php
require_once __DIR__.'/includes/functions.php';$featured=db()->query("SELECT n.*,c.name category,c.slug category_slug,u.name author FROM news n LEFT JOIN categories c ON c.id=n.category_id LEFT JOIN users u ON u.id=n.user_id WHERE n.status='published' AND n.deleted_at IS NULL AND n.is_featured=1 ORDER BY n.published_at DESC LIMIT 4")->fetchAll();$latest=db()->query("SELECT n.*,c.name category,c.slug category_slug,u.name author FROM news n LEFT JOIN categories c ON c.id=n.category_id LEFT JOIN users u ON u.id=n.user_id WHERE n.status='published' AND n.deleted_at IS NULL ORDER BY n.published_at DESC LIMIT 9")->fetchAll();$breaking=db()->query("SELECT title,slug FROM news WHERE status='published' AND deleted_at IS NULL AND is_breaking=1 ORDER BY published_at DESC LIMIT 6")->fetchAll();$popular=db()->query("SELECT title,slug,image,views_count FROM news WHERE status='published' AND deleted_at IS NULL ORDER BY views_count DESC LIMIT 5")->fetchAll();$sections=db()->query("SELECT c.id,c.name,c.slug,c.description FROM categories c WHERE EXISTS(SELECT 1 FROM news n WHERE n.category_id=c.id AND n.status='published' AND n.deleted_at IS NULL) ORDER BY c.name LIMIT 4")->fetchAll();$pageTitle='الرئيسية';require __DIR__.'/includes/header.php';?>
<?php if($breaking):?><div class="container mt-4"><div class="breaking p-3 d-flex gap-3 align-items-center"><span class="badge text-bg-danger">عاجل</span><div class="overflow-hidden"><div class="d-flex gap-5 text-nowrap"><?php foreach($breaking as $b):?><a class="text-decoration-none text-dark fw-semibold" href="<?=url('news.php?slug='.rawurlencode($b['slug']))?>"><?=e($b['title'])?></a><?php endforeach;?></div></div></div></div><?php endif;?>
<div class="container py-5"><?php if($featured):$hero=array_shift($featured);?><section class="mb-5"><h2 class="section-title">الأخبار المميزة</h2><div class="row g-4"><div class="col-lg-8"><article class="hero-card position-relative"><img src="<?=imageUrl($hero['image'])?>" alt="<?=e($hero['title'])?>"><div class="p-4"><a class="category-badge" href="<?=url('category.php?slug='.rawurlencode($hero['category_slug']))?>"><?=e($hero['category'])?></a><h1 class="h2 fw-bold my-3"><a class="text-dark text-decoration-none" href="<?=url('news.php?slug='.rawurlencode($hero['slug']))?>"><?=e($hero['title'])?></a></h1><p class="text-secondary"><?=e($hero['summary'])?></p></div></article></div><div class="col-lg-4 d-flex flex-column gap-3"><?php foreach($featured as $f):?><article class="news-card"><div class="row g-0"><div class="col-5"><img class="h-100" src="<?=imageUrl($f['image'])?>"></div><div class="col-7 p-3"><span class="text-danger small"><?=e($f['category'])?></span><h3 class="h6 fw-bold mt-2"><a class="text-dark text-decoration-none" href="<?=url('news.php?slug='.rawurlencode($f['slug']))?>"><?=e($f['title'])?></a></h3></div></div></article><?php endforeach;?></div></div></section><?php endif;?><div class="row g-4"><div class="col-lg-8"><section><h2 class="section-title">أحدث الأخبار</h2><div class="row g-4"><?php foreach($latest as $a):?><div class="col-md-6"><article class="news-card"><img src="<?=imageUrl($a['image'])?>" alt="<?=e($a['title'])?>"><div class="p-3"><a class="category-badge" href="<?=url('category.php?slug='.rawurlencode($a['category_slug']))?>"><?=e($a['category'])?></a><h3 class="h5 fw-bold mt-3"><a class="text-dark text-decoration-none" href="<?=url('news.php?slug='.rawurlencode($a['slug']))?>"><?=e($a['title'])?></a></h3><p class="text-secondary small"><?=e(excerpt($a['summary'],100))?></p><div class="article-meta"><i class="bi bi-clock"></i> <?=formatDate($a['published_at'])?> · <i class="bi bi-eye"></i> <?=$a['views_count']?></div></div></article></div><?php endforeach;if(!$latest):?><div class="col-12"><div class="panel p-5 text-center text-secondary">لا توجد أخبار منشورة حتى الآن.</div></div><?php endif;?></div></section></div><aside class="col-lg-4"><div class="panel p-4 sticky-lg-top" style="top:95px"><h3 class="section-title h5">الأكثر قراءة</h3><?php foreach($popular as $i=>$p):?><a class="d-flex gap-3 py-3 border-bottom text-decoration-none text-dark" href="<?=url('news.php?slug='.rawurlencode($p['slug']))?>"><span class="fs-3 fw-bold text-danger">0<?=$i+1?></span><span><strong><?=e($p['title'])?></strong><small class="d-block text-secondary"><i class="bi bi-eye"></i> <?=$p['views_count']?></small></span></a><?php endforeach;?></div></aside></div><?php foreach($sections as $sec):$s=db()->prepare("SELECT title,slug,image,summary FROM news WHERE category_id=? AND status='published' AND deleted_at IS NULL ORDER BY published_at DESC LIMIT 3");$s->execute([$sec['id']]);$items=$s->fetchAll();?><section class="mt-5"><div class="d-flex justify-content-between"><h2 class="section-title"><?=e($sec['name'])?></h2><a href="<?=url('category.php?slug='.rawurlencode($sec['slug']))?>">عرض الكل</a></div><div class="row g-4"><?php foreach($items as $a):?><div class="col-md-4"><article class="news-card"><img src="<?=imageUrl($a['image'])?>"><div class="p-3"><h3 class="h5 fw-bold"><a class="text-dark text-decoration-none" href="<?=url('news.php?slug='.rawurlencode($a['slug']))?>"><?=e($a['title'])?></a></h3><p class="small text-secondary"><?=e(excerpt($a['summary'],90))?></p></div></article></div><?php endforeach;?></div></section><?php endforeach;?></div><?php require __DIR__.'/includes/footer.php';?>
